# NexusHost mod installer. Runs in Windows PowerShell 5.1 or later.
# Generated by build-installer.ps1. Don't edit the generated .bat by hand.
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}

$ServerName  = '__SERVER_NAME__'
$ServerIp    = '__SERVER_IP__'
$McVersion   = '__MC_VERSION__'
$Loader      = '__LOADER__'
$DataVersion = '__DATA_VERSION__'
$ProfileKey  = '__PROFILE_KEY__'
$ProfileName = "$ServerName (Fabric $McVersion)"
$FabricProfileB64 = '__FABRIC_PROFILE_B64__'
$Manifest = @'
__MANIFEST__
'@

function Say([string]$msg, [string]$color = '') { if ($color) { Write-Host $msg -ForegroundColor $color } else { Write-Host $msg } }
function Fail([string]$msg) {
  Say ''
  Say "ERROR: $msg" 'Red'
  Say 'Send a screenshot of this window to the server host.' 'Yellow'
  exit 1
}
function Download([string]$url, [string]$dest) {
  $curl = Join-Path $env:SystemRoot 'System32\curl.exe'
  if (Test-Path $curl) {
    & $curl -sSLf --retry 3 -o $dest $url
    if ($LASTEXITCODE -ne 0) { throw "download failed (curl exit $LASTEXITCODE): $url" }
  } else {
    Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $dest
  }
}
function Sha512([string]$path) {
  $alg = [Security.Cryptography.SHA512]::Create(); $fs = [IO.File]::OpenRead($path)
  try { -join ($alg.ComputeHash($fs) | ForEach-Object { $_.ToString('x2') }) } finally { $fs.Dispose(); $alg.Dispose() }
}

Say ''
Say "=== $ServerName : mod installer (Minecraft $McVersion) ===" 'Cyan'
Say ''

$mc = Join-Path $env:APPDATA '.minecraft'
$lp = Join-Path $mc 'launcher_profiles.json'
if (-not (Test-Path -LiteralPath $lp)) {
  Fail "Minecraft Launcher data not found in $mc. Install the official Minecraft Launcher from minecraft.net, open it once and sign in, close it, then run this file again."
}

# The launcher rewrites launcher_profiles.json when it closes, erasing our profile, so it must be closed first.
# Classic launcher = MinecraftLauncher.exe, Microsoft Store/Xbox launcher = Minecraft.exe,
# running Java game = javaw.exe from the launcher's bundled runtime.
function Get-McRunning {
  @(Get-Process -ErrorAction SilentlyContinue | Where-Object {
    $_.ProcessName -eq 'MinecraftLauncher' -or $_.ProcessName -eq 'Minecraft' -or
    ($_.ProcessName -match '^javaw?$' -and "$($_.Path)" -match '\\runtime\\java-runtime|\.minecraft')
  })
}
if (-not $env:FS_INSTALLER_TEST) {
  while ((Get-McRunning).Count -gt 0) {
    Say 'Minecraft or the Minecraft Launcher is still open.' 'Yellow'
    Say 'Quit the game, close the launcher completely (also check the system tray), then press Enter.' 'Yellow'
    [void](Read-Host)
  }
}

$gameDir = Join-Path $mc $ProfileKey
$dirs = @{ mod = 'mods'; shader = 'shaderpacks'; resourcepack = 'resourcepacks' }
foreach ($d in @('', 'mods', 'shaderpacks', 'resourcepacks', 'config')) { New-Item -ItemType Directory -Force -Path (Join-Path $gameDir $d) | Out-Null }

# 1. Fabric loader
$vid  = "fabric-loader-$Loader-$McVersion"
$vdir = Join-Path $mc "versions\$vid"
New-Item -ItemType Directory -Force -Path $vdir | Out-Null
[IO.File]::WriteAllBytes((Join-Path $vdir "$vid.json"), [Convert]::FromBase64String($FabricProfileB64))
$dummyJar = Join-Path $vdir "$vid.jar"
if (-not (Test-Path -LiteralPath $dummyJar)) { [IO.File]::WriteAllBytes($dummyJar, [byte[]]@()) }
Say "[1/4] Fabric Loader $Loader installed" 'Green'

# 2. Mods, shaders, resource packs
$entries = @($Manifest -split "`r?`n" | Where-Object { $_.Trim() } | ForEach-Object {
  $p = $_ -split '\|'
  New-Object psobject -Property @{ kind = $p[0]; title = $p[1]; file = $p[2]; url = $p[3]; sha512 = $p[4] }
})
$keep = @($entries | ForEach-Object { $_.file })
$modsDir = Join-Path $gameDir 'mods'
$old = @(Get-ChildItem -LiteralPath $modsDir -Filter '*.jar' | Where-Object { $keep -notcontains $_.Name })
if ($old.Count -gt 0) {
  $oldDir = Join-Path $gameDir 'mods-old'
  New-Item -ItemType Directory -Force -Path $oldDir | Out-Null
  foreach ($o in $old) { Move-Item -LiteralPath $o.FullName -Destination (Join-Path $oldDir $o.Name) -Force; Say "      moved outdated mod to mods-old: $($o.Name)" 'DarkGray' }
}
Say "[2/4] Downloading $($entries.Count) files from Modrinth (first time takes a minute)..." 'Green'
$i = 0
foreach ($e in $entries) {
  $i++
  $dest = Join-Path (Join-Path $gameDir $dirs[$e.kind]) $e.file
  $label = '      ({0,2}/{1}) {2}' -f $i, $entries.Count, $e.title
  if ((Test-Path -LiteralPath $dest) -and ((Sha512 $dest) -eq $e.sha512)) { Say "$label - already installed" 'DarkGray'; continue }
  $tmp = "$dest.part"
  try { Download $e.url $tmp } catch { Fail "Could not download $($e.title). Check your internet connection and run again. ($_)" }
  if ((Sha512 $tmp) -ne $e.sha512) { Remove-Item -LiteralPath $tmp -Force; Fail "$($e.title) failed its integrity check. Run the installer again." }
  Move-Item -LiteralPath $tmp -Destination $dest -Force
  Say $label
}

# 3. First-time settings (an existing file is never overwritten)
$fresh  = ($entries | Where-Object { $_.kind -eq 'resourcepack' } | Select-Object -First 1).file
$shader = ($entries | Where-Object { $_.kind -eq 'shader' } | Select-Object -First 1).file
$utf8 = New-Object Text.UTF8Encoding $false
$opt = Join-Path $gameDir 'options.txt'
if (-not (Test-Path -LiteralPath $opt)) {
  $packs = '["vanilla"]'
  if ($fresh) { $packs = '["vanilla","file/' + $fresh + '"]' }
  [IO.File]::WriteAllText($opt, "version:$DataVersion`nresourcePacks:$packs`nrenderDistance:8`nsimulationDistance:8`n", $utf8)
}
$iris = Join-Path $gameDir 'config\iris.properties'
if ($shader -and -not (Test-Path -LiteralPath $iris)) {
  [IO.File]::WriteAllText($iris, "enableShaders=true`nshaderPack=$shader`n", $utf8)
}
# Add the server to the multiplayer list (servers.dat, uncompressed NBT)
$sd = Join-Path $gameDir 'servers.dat'
if (-not (Test-Path -LiteralPath $sd)) {
  $ms = New-Object IO.MemoryStream
  function W-Byte([int]$b) { $ms.WriteByte([byte]$b) }
  function W-Str([string]$s) { $b = [Text.Encoding]::UTF8.GetBytes($s); W-Byte (($b.Length -shr 8) -band 0xFF); W-Byte ($b.Length -band 0xFF); $ms.Write($b, 0, $b.Length) }
  W-Byte 10; W-Str ''                                   # root compound
  W-Byte 9;  W-Str 'servers'; W-Byte 10; W-Byte 0; W-Byte 0; W-Byte 0; W-Byte 1   # list of 1 compound
  W-Byte 8;  W-Str 'name'; W-Str $ServerName
  W-Byte 8;  W-Str 'ip';   W-Str $ServerIp
  W-Byte 1;  W-Str 'acceptTextures'; W-Byte 1
  W-Byte 0                                              # end of server entry
  W-Byte 0                                              # end of root
  [IO.File]::WriteAllBytes($sd, $ms.ToArray())
}
Say '[3/4] Settings ready: default shader and resource pack on, server added to the Multiplayer list' 'Green'

# 4. Launcher profile
try {
  Copy-Item -LiteralPath $lp -Destination "$lp.before-$ProfileKey" -Force
  $data = [IO.File]::ReadAllText($lp) | ConvertFrom-Json
  if (-not $data.profiles) { $data | Add-Member -NotePropertyName profiles -NotePropertyValue (New-Object psobject) }
  $ramGB = [math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB)
  $heap = 2; if ($ramGB -ge 8) { $heap = 3 }; if ($ramGB -ge 12) { $heap = 4 }
  $now = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ')
  $prof = New-Object psobject -Property ([ordered]@{
    name = $ProfileName; type = 'custom'; created = $now; lastUsed = $now; lastVersionId = $vid
    gameDir = $gameDir; icon = 'Crafting_Table'
    javaArgs = "-Xmx${heap}G -Xms${heap}G -XX:+UnlockExperimentalVMOptions -XX:+UseG1GC -XX:G1NewSizePercent=20 -XX:G1ReservePercent=20 -XX:MaxGCPauseMillis=50 -XX:G1HeapRegionSize=32M"
  })
  if ($data.profiles.PSObject.Properties[$ProfileKey]) { $data.profiles.$ProfileKey = $prof }
  else { $data.profiles | Add-Member -NotePropertyName $ProfileKey -NotePropertyValue $prof }
  [IO.File]::WriteAllText($lp, ($data | ConvertTo-Json -Depth 32), $utf8)
} catch { Fail "Could not update the Minecraft Launcher profile list: $_" }
Say "[4/4] Launcher profile '$ProfileName' created ($heap GB RAM for the game)" 'Green'
if (-not $env:FS_INSTALLER_TEST -and (Get-McRunning).Count -gt 0) {
  Say ''
  Say 'WARNING: the Minecraft Launcher was opened while installing. Close it and run this installer again,' 'Red'
  Say 'otherwise the launcher may erase the new profile.' 'Red'
}

Say ''
Say 'ALL DONE!' 'Cyan'
Say '  1. Open the Minecraft Launcher.'
Say "  2. Next to the green PLAY button, pick '$ProfileName'."
Say '  3. Press PLAY. The first start takes a little longer.'
Say "  4. Multiplayer -> '$ServerName' is already in your list."
Say ''
Say 'In game: press K to turn shaders on/off, M opens the world map, C zooms.' 'DarkGray'
$ts = Join-Path $env:ProgramFiles 'Tailscale\tailscale.exe'
if (-not (Test-Path -LiteralPath $ts)) {
  Say ''
  Say 'Tailscale is NOT installed. You need it to reach the server. Opening the download page...' 'Yellow'
  if (-not $env:FS_INSTALLER_TEST) { Start-Process 'https://tailscale.com/download/windows' }
} else {
  Say 'Remember: Tailscale must be connected before you join.' 'DarkGray'
}
